      const x = d3.scaleLinear().domain([Math.min(0.88, lo - 0.005), Math.max(0.92, hi + 0.005)]).range([lab, W - 16]);
      const yOf = i => top + i * rh + (i >= gapAt ? 16 : 0) + rh / 2;
